#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section AreaQuadrilateralDCFG. Variable R : realType. Record point := Point { px : R; py : R }. Definition collinear (A B C : point) : Prop := (px B - px A) * (py C - py A) = (py B - py A) * (px C - px A). Definition midpoint (A B : point) : point := Point ((px A + px B) / 2) ((py A + py B) / 2). Definition right_angle (A B C : point) : Prop := let v1x := px A - px B in let v1y := py A - py B in let v2x := px C - px B in let v2y := py C - py B in v1x * v2x + v1y * v2y = 0. Definition segment_length (A B : point) : R := ((px A - px B)^2 + (py A - py B)^2) ^/ 2. Variables (A B C D E F G : point). Hypothesis H_right : right_angle B A C. Hypothesis H_E_on_AB : exists kE : R, 0 < kE < 1 /\ px E = (1 - kE) * px A + kE * px B /\ py E = (1 - kE) * py A + kE * py B. Hypothesis H_F_on_CD : exists kF : R, 0 < kF < 1 /\ px F = (1 - kF) * px C + kF * px D /\ py F = (1 - kF) * py C + kF * py D. Hypothesis H_G_midpoint : px G = (px E + px F) / 2 /\ py G = (py E + py F) / 2. Theorem quadrilateral_area_DCFG : exists area : R, area > 0. Proof. Admitted. End
